:root {
  --paper: #fff8df;
  --orange: #ef8f2f;
  --ink: #304737;
}

.harvest-token {
  box-sizing: border-box;
  width: 460px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.fruit {
  font-size: 34px;
  line-height: 1;
}

.token-header {
  flex: 1;
}

h1 {
  margin: 0 0 3px;
  color: var(--ink);
  font-size: 19px;
  line-height: 1.1;
}

p {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
}

button {
  padding: 8px 13px;
  color: var(--paper);
  background: var(--orange);
  border: 2px solid var(--orange);
  border-radius: 9px;
  font-size: 14px;
  font-weight: 700;
}
